/// A compile-time constant cannot call [_contactLine], so the paragraph is a
/// marker replaced when a document is read through [legalDocuments].
const _contactLineMarker = '{{contact}}';

/// Every document, in the order the app lists them, with markers resolved.
List<LegalDocument> get legalDocuments => [kTermsOfService, kPrivacyPolicy].map(_resolve).toList();

LegalDocument legalDocumentById(String id) => legalDocuments.firstWhere((d) => d.id == id);

LegalDocument _resolve(LegalDocument d) => LegalDocument(
      id: d.id,
      title: d.title,
      version: d.version,
      effectiveDate: d.effectiveDate,
      summary: d.summary,
      sections: [
        for (final s in d.sections)
          LegalSection(
            s.heading,
            paragraphs: s.paragraphs.map(_fill).toList(),
            bullets: s.bullets.map(_fill).toList(),
            after: s.after.map(_fill).toList(),
          ),
      ],
    );

String _fill(String text) => text.replaceAll(_contactLineMarker, _contactLine());

/// The facts above that still read as placeholders — what must be filled in
/// before these documents are shown to a real shop. Empty when complete.
List<String> legalPlaceholdersLeft() => [
      for (final value in [
        kLegalEntityName,
        kLegalEntityAddress,
        kGrievanceOfficerName,
        kGrievanceEmail,
        kSupportEmail,
        kJurisdictionCity,
      ])
        if (value.startsWith('[') && value.endsWith(']')) value,
    ];

/// The documents as Markdown — what `tool/export_legal.dart` writes to the
/// vault, and what the web app can serve.
String legalDocumentToMarkdown(LegalDocument doc) {
  final d = _resolve(doc);
  final out = StringBuffer()
    ..writeln('# ${d.title}')
    ..writeln()
    ..writeln('Version ${d.version} · Effective ${d.effectiveDate}')
    ..writeln()
    ..writeln(d.summary)
    ..writeln();
  for (final s in d.sections) {
    out
      ..writeln('## ${s.heading}')
      ..writeln();
    for (final p in s.paragraphs) {
      out
        ..writeln(p)
        ..writeln();
    }
    for (final b in s.bullets) {
      out.writeln('- $b');
    }
    if (s.bullets.isNotEmpty) out.writeln();
    for (final p in s.after) {
      out
        ..writeln(p)
        ..writeln();
    }
  }
  return out.toString();
}
